31	// Validate the lone-ELF positional shape the standalone models require: print
32	// the diagnostic and return 2 on a violation, else 0. `model` labels the error.
33	int check_one_elf(const Cli& cli, const char* model) {
34	  if (cli.positional.empty()) {
35	    std::fprintf(stderr,
36	                 "andesim run --mode %s: missing ELF (the workload to run; "
37	                 "e.g. a tests/fixtures/<name>.elf)\n",
38	                 model);
39	    return 2;
40	  }
41	  if (cli.positional.size() > 1) {
42	    std::fprintf(stderr,
43	                 "andesim run --mode %s: unexpected argument '%s' "
44	                 "(engine args go after --)\n",
45	                 model, cli.positional[1].c_str());
46	    return 2;
47	  }
48	  return 0;
49	}
50	
51	// The standalone spine shared by `fast` and `cycle`: both take a single ELF,
52	// then run the resolved engine standalone with `extra` framework-injected args
53	// (e.g. fast's --mem-size `-m`) followed by the post-`--` args forwarded
54	// verbatim, inheriting stdio (an interactive gdbstub / monitor / semihosting
55	// console works unchanged) and propagating the exit code. `extra` precedes the
56	// user's passthrough so a user's own flag wins. The per-model engine +
57	// selection are resolved by the caller; `model` here only labels the positional
58	// diagnostics. This minimal slice does no ELF existence/arch validation (that
59	// lands with strict validation).
60	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
61	                   const char* model, const std::vector<std::string>& extra = {}) {
62	  if (int rc = check_one_elf(cli, model)) return rc;
63	  std::vector<std::string> args = extra;
64	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
65	  std::string err;
66	  const std::vector<std::string> argv =
67	      passthrough_argv(eng, "standalone", cli.positional[0], args, err);
68	  if (!err.empty()) {
69	    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
70	    return 2;
71	  }
72	  return exec_passthrough(argv);
73	}
74	
75	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Resolves
76	// the built-in qemu descriptor directly (no engine discovery -- fast needs only
77	// qemu, and discover_engines would spawn a --describe per Verilator build).
78	int run_fast(const Cli& cli) {
79	  // fast is QEMU-only; an explicit engine must name it.
80	  if (!cli.engine.empty() && cli.engine != "qemu") {
81	    std::fprintf(stderr,
82	                 "andesim run --mode fast: engine must be 'qemu', got '%s'\n",
83	                 cli.engine.c_str());
84	    return 2;
85	  }
86	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
87	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
88	  std::string err;
89	  std::vector<std::string> extra = qemu_m_args(cli.mem_size, err);
90	  if (!err.empty()) {
91	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
92	    return 2;
93	  }
94	  return run_standalone(cli, builtin_qemu(), "fast", extra);
95	}
96	
97	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
98	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
99	// engine's own output. Unlike fast, this must discover the Verilator build(s)
100	// to resolve the engine (explicit --engine, else the sole one).
101	int run_accurate(const Cli& cli) {
102	  // --mem-size is validated but has nothing to size: the cycle engine always
103	  // models its full DRAM window. Say so instead of silently ignoring it.
104	  if (!cli.mem_size.empty()) {
105	    std::string se;
106	    if (parse_size(cli.mem_size, se); !se.empty()) {
107	      std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
108	                   se.c_str());
109	      return 2;
110	    }
111	    std::fprintf(stderr,
112	                 "[andesim] --mem-size: the cycle engine models its full "
113	                 "DRAM window; nothing to size\n");
114	  }
115	  Discovery disc = discover_engines();
116	  std::string err;
117	  const EngineDescriptor* eng =
118	      resolve_accurate_engine(disc.engines, cli.engine, err);
119	  if (!eng) {
120	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
121	    // Surface why an expected engine may be absent (failed --describe, etc.).
122	    for (const std::string& w : disc.warnings)
123	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
124	    return 2;
125	  }
126	  return run_standalone(cli, *eng, "cycle");
127	}
128	
129	// `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
130	// handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle figure
131	// is the vsim mcycle minus QEMU1's drained mcycle. This slice builds the 2-step
132	// plan and runs it; the exact per-leg dry-run command lines, --mem-size, and
133	// --verify land as the feature grows.
134	int run_hybrid(const Cli& cli) {
135	  auto fail = [](const std::string& msg) {
136	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
137	    return 2;
138	  };
139	
140	  if (int rc = check_one_elf(cli, "hybrid")) return rc;
141	  const std::string elf = cli.positional[0];
142	
143	  std::string err;
144	  const Trigger trig = hybrid_trigger(cli, elf, err);
145	  if (!err.empty()) return fail(err);
146	
147	  // --mem-size sizes the shared mmap (= QEMU backend = vsim window); the 2 GiB
148	  // cap + ELF-fit reject ride the V-scratch work. Empty spec keeps the default.
149	  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
150	  if (!cli.mem_size.empty()) {
151	    std::string se;
152	    mem = parse_size(cli.mem_size, se);
153	    if (!se.empty()) return fail("--mem-size: " + se);
154	  }
155	
156	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
157	  // or the sole cycle-accurate engine (reusing the F8 selector).
158	  Discovery disc = discover_engines();
159	  const EngineDescriptor* acc =
160	      resolve_accurate_engine(disc.engines, cli.engine, err);
161	  if (!acc) {
162	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", err.c_str());
163	    for (const std::string& w : disc.warnings)
164	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
165	    return 2;
166	  }
167	
168	  Plan plan;
169	  plan.elf = elf;
170	  plan.mem_size = mem;
171	  plan.steps = {
172	      Step{"qemu", "fast-leg", trig},
173	      Step{acc->id, "accurate-leg", trig},
174	  };
175	
176	  // Banner to stderr so the window-cycle result stands alone on stdout.
177	  const std::string fixture = fs::path(elf).stem().string();
178	  std::fprintf(stderr, "[andesim] model=hybrid engine=%s trigger=%s fixture=%s\n",
179	               acc->id.c_str(), trig.kind.c_str(), fixture.c_str());
180	
181	  // --dry-run: report the 2-step plan and spawn nothing. The exact per-leg
182	  // command lines land with the dry-run print feature; here we confirm the
183	  // plan the handoff would run.
184	  if (cli.dry_run) {
185	    std::printf("[andesim] dry-run: %zu-step plan (spawns nothing)\n",
186	                plan.steps.size());
187	    for (size_t i = 0; i < plan.steps.size(); ++i)
188	      std::printf("# step %zu/%zu: %s [%s]\n", i + 1, plan.steps.size(),
189	                  plan.steps[i].role.c_str(), plan.steps[i].engine_id.c_str());
190	    return 0;
191	  }
192	
193	  const PlanResult r = run_plan(plan, disc.engines);
194	  if (!r.ok()) {
195	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", r.error.c_str());
196	    return 1;
197	  }
198	  // phases[0] = QEMU1 drain, [1] = vsim drain; the window figure is the vsim
199	  // mcycle delta.
200	  const unsigned long long q_mc = r.phases[0].mcycle;
201	  const unsigned long long v_mc = r.phases[1].mcycle;
202	  std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
203	              trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
204	  std::printf("PASS: --mode hybrid --trigger %s (%s)\n", trig.kind.c_str(),
205	              fixture.c_str());
206	  return 0;
207	}
208	
209	}  // namespace
