211	int cmd_run(const Cli& cli) {
212	  if (cli.model.empty()) {
213	    std::fprintf(stderr,
214	                 "andesim run: --mode fast|cycle|hybrid is required "
215	                 "(pick the composition; see 'andesim run --help')\n");
216	    return 2;
217	  }
218	  if (!find_model(cli.model)) {
219	    std::fprintf(stderr,
220	                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
221	                 cli.model.c_str());
222	    return 2;
223	  }
224	  if (cli.model == "fast") return run_fast(cli);
225	  if (cli.model == "cycle") return run_accurate(cli);
226	  return run_hybrid(cli);  // model validated above; only hybrid remains
227	}
