21	// Each leg's drain file, threaded forward (leg i+1 resumes from leg i's).
22	std::string state_path(const std::string& workdir, size_t i) {
23	  return workdir + "/state-" + std::to_string(i) + ".bin";
24	}
25	
26	const EngineDescriptor* find_engine(const std::vector<EngineDescriptor>& engines,
27	                                    const std::string& id) {
28	  for (const EngineDescriptor& e : engines)
29	    if (e.id == id) return &e;
30	  return nullptr;
31	}
32	
33	// $VSIM_PLUGIN else the in-repo default (matches the e2e harness).
34	std::string resolve_plugin(const std::string& override_path) {
35	  if (!override_path.empty()) return override_path;
36	  if (const char* p = std::getenv("VSIM_PLUGIN"); p && *p) return p;
37	  return default_plugin_path().string();
38	}
