41	
42	std::vector<std::vector<std::string>> plan_argvs(
43	    const Plan& plan, const std::vector<EngineDescriptor>& engines,
44	    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
45	  std::vector<std::vector<std::string>> out;
46	  out.reserve(plan.steps.size());
47	  std::string prev_state_out;  // empty for the cold first leg
48	
49	  for (size_t i = 0; i < plan.steps.size(); ++i) {
50	    const Step& step = plan.steps[i];
51	    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
52	    if (!eng) {
53	      err = "plan step " + std::to_string(i) + ": unknown engine '" +
54	            step.engine_id + "'";
55	      return {};
56	    }
57	    const std::vector<std::string>* tmpl = eng->invoke_for(step.role);
58	    if (!tmpl) {
59	      err = "plan step " + std::to_string(i) + ": engine '" + step.engine_id +
60	            "' has no invoke template for role '" + step.role + "'";
61	      return {};
62	    }
63	
64	    const std::string state_out = state_path(workdir, i);
65	    const std::map<std::string, std::string> m = {
66	        {"bin", eng->bin_path},
67	        {"elf", plan.elf},
68	        {"plugin", ctx.plugin_path},
69	        {"mmap", ctx.mmap_path},
70	        {"mmap_size", std::to_string(ctx.mem_size)},
71	        {"mmap_base", ctx.mmap_base},
72	        {"state_in", prev_state_out},
73	        {"state_out", state_out},
74	    };
75	    std::vector<std::string> argv = build_argv(*tmpl, m, err);
76	    if (!err.empty()) {
77	      err = "plan step " + std::to_string(i) + ": " + err;
78	      return {};
79	    }
80	    out.push_back(std::move(argv));
81	    prev_state_out = state_out;
82	  }
83	  err.clear();
84	  return out;
85	}
86	
87	PlanResult run_plan(const Plan& plan,
88	                    const std::vector<EngineDescriptor>& engines,
89	                    const PlanOptions& opts) {
90	  PlanResult res;
91	  if (plan.steps.empty()) {
92	    res.error = "plan has no steps";
93	    return res;
94	  }
95	
96	  // Acquire the shared mmap: allocate one under /dev/shm (and own it) when the
97	  // caller pinned none, so QEMU1's guest memory survives into the vsim leg.
98	  std::string mmap_path = plan.mmap_path;
99	  const bool own_mmap = mmap_path.empty();
100	  if (own_mmap) {
101	    std::string err;
102	    mmap_path = allocate(plan.mem_size, err);
103	    if (mmap_path.empty()) {
104	      res.error = err;
105	      return res;
106	    }
107	  }
108	
109	  // A private dir for the per-leg drain files each leg writes via {state_out}.
110	  std::error_code ec;
111	  fs::path workdir = fs::temp_directory_path(ec) / "andesim-plan-XXXXXX";
112	  std::string tmpl = workdir.string();
113	  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
114	  tbuf.push_back('\0');
115	  const char* made = ::mkdtemp(tbuf.data());
116	  if (!made) {
117	    if (own_mmap) ::unlink(mmap_path.c_str());
118	    res.error = "failed to create plan work dir";
119	    return res;
120	  }
121	  const std::string wd = made;
122	
123	  RuntimeCtx ctx;
124	  ctx.mmap_path = mmap_path;
125	  ctx.mem_size = plan.mem_size;
126	  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps "0x0"
127	
128	  std::string err;
129	  const std::vector<std::vector<std::string>> argvs =
130	      plan_argvs(plan, engines, wd, ctx, err);
131	  if (!err.empty()) {
132	    res.error = err;
133	  } else {
134	    for (size_t i = 0; i < argvs.size(); ++i) {
135	      const RunResult r = run_process(argvs[i], opts.timeout_ms);
136	      if (r.spawn_failed) {
137	        res.error = "plan step " + std::to_string(i) + ": failed to spawn";
138	        break;
139	      }
140	      if (r.timed_out) {
141	        res.error = "plan step " + std::to_string(i) + ": timed out after " +
142	                    std::to_string(opts.timeout_ms) + " ms";
143	        break;
144	      }
145	      if (r.rc != opts.expect_rc) {
146	        res.error = "plan step " + std::to_string(i) + ": expected exit " +
147	                    std::to_string(opts.expect_rc) + ", got " +
148	                    std::to_string(r.rc);
149	        break;
150	      }
151	      // Read back this leg's drained state; the hybrid cycle figure is the
152	      // vsim-leg mcycle minus the qemu-leg mcycle.
153	      const StateFile sf = read_state_file(state_path(wd, i));
154	      if (!sf.ok()) {
155	        res.error = "plan step " + std::to_string(i) + ": " + sf.error;
156	        break;
157	      }
158	      res.phases.push_back({sf.st.mcycle, sf.st.minstret});
159	    }
160	  }
161	
162	  fs::remove_all(wd, ec);
163	  if (own_mmap) ::unlink(mmap_path.c_str());
164	  return res;
165	}
