68	// Validate the lone-ELF positional shape the standalone models require: print
69	// the diagnostic and return 2 on a violation, else 0. Split out so `cycle`
70	// can reject a missing/extra ELF BEFORE paying for engine discovery (which
71	// spawns a --describe subprocess per Verilator build). `model` labels the error.
72	int check_one_elf(const Cli& cli, const char* model) {
73	  if (cli.positional.empty()) {
74	    std::fprintf(stderr,
75	                 "andesim run --mode %s: missing ELF (the workload to run; "
76	                 "e.g. a tests/fixtures/<name>.elf)\n",
77	                 model);
78	    return 2;
79	  }
80	  if (cli.positional.size() > 1) {
81	    std::fprintf(stderr,
82	                 "andesim run --mode %s: unexpected argument '%s' "
83	                 "(engine args go after --)\n",
84	                 model, cli.positional[1].c_str());
85	    return 2;
86	  }
87	  return 0;
88	}
